    (6820400, "被ダメージ時の発狂蓄積。リブラ（とナメレス）以外では蓄積されにくい。狂い火の祈祷・戦技と併用するなら注意（KW-遺物効果）"),
    (6850700, "回避直後のカット率-45%（データの name_ja「回避直後の被ダメージ増加」は誤りとみられる）。無頼漢は回避の無敵が短いので特に注意、鉄の目はやや軽い（KW-遺物効果）"),
