# ================================================================ rendering
E = None          # effects dict, loaded in main()
UNRELEASED = set()


def is_relic(i):
    return i < 200000 or 6000000 <= i <= 7399999


def fmt_id(i):
    v = E.get(str(i))
    if v is None or not is_relic(i):
        raise SystemExit(f"unknown/non-relic effect id {i}")
    if i in UNRELEASED:
        raise SystemExit(f"unreleased effect id {i} must not be listed")
    return f"{NAME_OVERRIDE.get(i, v['name_ja'])} `{v['key']}` ({i})"


def entry_ids(x):
    if isinstance(x, tuple) and x and x[0] in ("NOTE", "MISSING"):
        return []
    if isinstance(x, tuple):
        x = x[0]
    return [x] if isinstance(x, int) else list(x)


def fmt_entry(x):
    if isinstance(x, tuple) and x and x[0] == "NOTE":
        return f"- {x[1]}（効果の種類をまとめた注記）" + (f" — {x[2]}" if len(x) > 2 and x[2] else "")
    if isinstance(x, tuple) and x and x[0] == "MISSING":
        return f"- {x[1]} **（effects_data.json に該当なし）**" + (f" — {x[2]}" if len(x) > 2 and x[2] else "")
    note = ""
    if isinstance(x, tuple):
        ids, note = x
    else:
        ids = x
    if isinstance(ids, int):
        ids = (ids,)
    body = " / ".join(fmt_id(i) for i in ids)
    return f"- {body}" + (f" — {note}" if note else "")


def section_list(title, items, empty="- （wiki に記載なし）"):
    out = [f"**{title}**", ""]
    out += [fmt_entry(x) for x in items] if items else [empty]
    out.append("")
    return out


def render():
    lines = []
    L = lines.append
    L("# ELDEN RING NIGHTREIGN キャラ別 遺物構成リサーチ（神攻略wiki 版）")
    L("")
    L("調査日: 2026-10-28。対象は ELDEN RING NIGHTREIGN のみ（無印エルデンリングの情報は除外）。")
    L("")
    L("## 方針と凡例")
    L("")
    L("- **出典は 神攻略wiki（https://kamikouryaku.net/nightreign_eldenring/）のみ**。各キャラページ（おすすめ遺物・深き夜考察・ビルド例）、遺物／遺物効果ページ、ビルド投稿（プレイヤー投稿）から組み直した。公式パッチノートは日付と版の確認にだけ使った。")
    L("- ビルド投稿は個人の構成。出典欄に投稿日・更新日、投稿者が書いた想定モードと深度（書かれていれば）を付けた。新形式のビルド投稿はすべて 2026-07 以降の投稿で、遺物効果を最後に変更した App 1.03.2 / Regulation 1.03.4（2026-01-15, OFF-1032）より後。")
    L("- 未実装の効果は一切載せていない（生成時に effects_data.json の unreleased の印と照合し、含まれていたら停止する）。")
    L("- wiki 内で評価が割れる効果（ある投稿は必須、別の投稿・ページは不要／回避など）は **任意** に置き、注意点に両方の意見を出典つきで書いた。")
    L("- 効果名と key は `resources/effects_data.json` から自動で引いている。表記は `name_ja` `key` (id)。id の範囲では通常／深層の枠を判断しない（6xxxxxx の効果も通常の遺物に付くことがある）。枠に触れるのは wiki・投稿にそう書かれている場合だけ。")
    L("- 6850700 はデータの name_ja（「回避直後の被ダメージ増加」）ではなく、ゲーム内・wiki の表記「回避直後、カット率低下」で表示している。")
    L("- ビルド数に上限は設けていない。wiki（キャラページのビルド例・おすすめ遺物の各型、ビルド投稿、未移行の旧ビルド投稿）にある型はすべて載せ、狙いも効果もほぼ同じ本当の重複だけをまとめた。特定の夜の王などに向けたビルドは **対象** 欄に書いた（空欄＝汎用）。")
    L("- 4段階: **必須級**＝そのビルドを定義する効果だけ（ビルドの軸になる戦技・魔術・祈祷・スキル、武器ビルドのその武器種強化、軸になる固有遺物やステ変、状態異常の付与手段など）。**推奨**＝キャラページの推奨や代表的な投稿の構成に入る。**任意**＝状況次第・一部の投稿のみ・ボス別・評価が割れる。**避けたい**＝wiki が避けるべきとする効果。")
    L("- キャラ全体の定番（どの型でもほぼ入る効果。例: レディのスキル無敵、撃破時アーツ、夜の侵入者、最大HP）は、1つのビルドだけ必須級にすることはせず、各キャラの冒頭「キャラ共通の定番」にまとめた。各ビルドでも推奨か任意に揃えている。")
    L("- 「刀・出血」のように、狙いは武器と状態異常・仕組みの組み合わせで書いた（例: 執行者の刀は初めから出血を持つので、冷気を足すと「刀・出血・凍傷」）。")
    L("- 名前付きの固有遺物・夜の王遺物（深海の夜＝赤マリス、深海の暗き夜＝青マリス、安寧の遺志＋安寧者の遺志＝ハルハル など）は、固定の効果に分けて書いた（KW-遺物）。")
    L("- 献器の key は `resources/vessels_data.json` のもの。`urn`=器、`goblet`=盃、`chalice`=高杯、`sootCoveredUrn`=煤けた器、`sealedUrn`=封じられた器、`decrepitGoblet`=朽ちた盃、`forgottenGoblet`=忘れられた盃。wiki に献器の記載がないビルドは「記載なし」とし、推定した場合はそう明記した。")
    L("- 「モード: 深層」は深き夜で通常枠3つ＋深層枠3つを使う構成。")
    L("")

    L("## 目次（キャラ別ビルド数）")
    L("")
    for char, builds in CH:
        tg = sum(1 for b in builds if b.get("target"))
        L(f"- {char}: {len(builds)} ビルド" + (f"（うち対象特化 {tg}）" if tg else ""))
    L("")

    for char, builds in CH:
        L(f"## {char}")
        L("")
        short = char.split(" ")[0]
        st = STAPLES.get(char)
        if st:
            L(f"### {short} — キャラ共通の定番")
            L("")
            lines.extend(section_list("推奨（どの型でもほぼ入る）", st.get("rec", [])))
            if st.get("opt"):
                lines.extend(section_list("任意（キャラ共通）", st["opt"]))
            if st.get("avoid"):
                lines.extend(section_list("避けたい（キャラ共通）", st["avoid"]))
            if st.get("notes"):
                L("**注意点**")
                L("")
                for n in st["notes"]:
                    L(f"- {n}")
                L("")
            if st.get("src"):
                L("**出典**: " + "、".join(f"[{c}]" for c in st["src"]))
                L("")
        for i, b in enumerate(builds, 1):
            L(f"### {short} — ビルド{i}: {b['name']}")
            L("")
            L(f"- **狙い（型）**: {b['aim']}")
            L(f"- **対象**: {b['target'] or '汎用'}")
            L(f"- **モード**: {b['mode']}")
            L(f"- **献器**: {b['vessel']}")
            L("")
            lines.extend(section_list("必須級", b.get("must", [])))
            lines.extend(section_list("推奨", b.get("rec", [])))
            lines.extend(section_list("任意", b.get("opt", [])))
            lines.extend(section_list("避けたい", b.get("avoid", []),
                                      "- （このビルド固有の記載なし。共通の避けたいデメリットは末尾を参照）"))
            if b.get("accept"):
                lines.extend(section_list("許容されているデメリット（参考）", b["accept"]))
            if b.get("notes"):
                L("**注意点**")
                L("")
                for n in b["notes"]:
                    L(f"- {n}")
                L("")
            L("**出典**")
            L("")
            for code in b["src"]:
                t, u, d = SRC[code]
                L(f"- [{code}] {t} — {u} （{d}）")
            L("")

    # ------------------------------------------------ cross-character frequency (data-driven, neutral)
    L("## キャラ横断: 必須級・推奨に入った回数の多い効果")
    L("")
    L("上の全ビルドの「必須級」「推奨」に何回入ったかを数えたもの（同じ効果の別 id・同ビルド内の重複は1回）。評価ではなく出現頻度。")
    L("")
    nb = sum(len(bs) for _, bs in CH)
    cnt, chars_of = {}, {}
    for char, builds in CH:
        for b in builds:
            seen = set()
            for x in b.get("must", []) + b.get("rec", []):
                for i in entry_ids(x):
                    k = E[str(i)]["key"]
                    if k in seen:
                        continue
                    seen.add(k)
                    cnt[k] = cnt.get(k, 0) + 1
                    chars_of.setdefault(k, set()).add(char.split(" ")[0])
    key_ids = {}
    for sid, v in E.items():
        if is_relic(int(sid)) and int(sid) not in UNRELEASED:
            key_ids.setdefault(v["key"], []).append(int(sid))
    L(f"| 効果 | key | 回数（全 {nb} ビルド中） | キャラ |")
    L("|---|---|---|---|")
    for k, c in sorted(cnt.items(), key=lambda t: (-t[1], t[0])):
        if c < 3:
            continue
        name = E[str(min(key_ids[k]))]["name_ja"]
        L(f"| {name} | `{k}` | {c} | {'・'.join(sorted(chars_of[k]))} |")
    L("")

    L("## 共通: 深層デメリットの評価（KW-遺物効果「デメリット効果」考察）")
    L("")
    lines.extend(section_list("避けたい（影響が大きい・外れとされる）", AVOID_COMMON))
    lines.extend(section_list("許容されがち（影響が小さい・当たりとされる）", ACCEPT_COMMON))
    lines.extend(section_list("キャラ・立ち回り次第（人によって評価が変わる）", MIXED_COMMON))
    L("- キャラごとの例外（例: アーツ主体キャラでのアーツゲージ蓄積鈍化、能力値低下の向き不向き）は各ビルドの避けたい／許容欄と注意点を参照。")
    L("")

    if QUESTIONS:
        L("## 確認したい点・不確かな点")
        L("")
        for q in QUESTIONS:
            L(f"- {q}")
        L("")

    L("## 出典一覧")
    L("")
    used = {c for _, bs in CH for b in bs for c in b["src"]}
    used |= {c for st in STAPLES.values() for c in st.get("src", [])}
    used |= {"KW-遺物効果", "KW-遺物", "KW-ビルド投稿", "OFF-1032"}
    for code, (t, u, d) in SRC.items():
        if code in used:
            L(f"- [{code}] {t} — {u} （{d}）")
    L("")
    return lines


def main(argv):
    global E, UNRELEASED
    eff = argv[1] if len(argv) > 1 else DEFAULT_EFFECTS
    out = argv[2] if len(argv) > 2 else DEFAULT_OUT
    E = json.load(open(eff, encoding="utf-8"))["effects"]
    # 未公開の効果（effects_data.json の "unreleased"）: 一切出力しない
    UNRELEASED = {int(k) for k, v in E.items() if v.get("unreleased")}
    # guard: no unreleased effect name may appear anywhere in free text either
    released_names = {v["name_ja"] for k, v in E.items() if int(k) not in UNRELEASED} | set(NAME_OVERRIDE.values())
    lines = render()
    text = "\n".join(lines)
    # strip released names (longest first) so that e.g. 「…、生命力低下」 inside a released name is not a false hit
    scrub = text
    for n in sorted(released_names, key=len, reverse=True):
        scrub = scrub.replace(n, "")
    for i in UNRELEASED:
        n = E[str(i)]["name_ja"]
        if n not in released_names and n in scrub:
            raise SystemExit(f"output mentions unreleased effect {i} {n}")
    for ch, bs in CH:
        for b in bs:
            if "target" not in b:
                raise SystemExit(f"{ch}/{b['name']}: missing target")
            for c in b["src"]:
                if not (c.startswith("KW-") or c == "OFF-1032"):
                    raise SystemExit(f"non-wiki source {c}")
    open(out, "w", encoding="utf-8").write(text)
    print("wrote", out, len(lines), "lines;", sum(len(b) for _, b in CH), "builds")


if __name__ == "__main__":
    main(sys.argv)
